const botToken = '8749798641:AAEH03Jl5rFqaNhmMwH8oayxM2eDlrd54_w';
const fileUrl = `https://api.telegram.org/file/bot${botToken}/${filePath}`;

const request_body = JSON.stringify({
  model: "google/gemini-2.5-flash",
  messages: [
    {
      role: "user",
      content: [
        {
          type: "image_url",
          image_url: {
            url: fileUrl
          }
        },
        {
          type: "text",
          text: `Ты — ассистент по учёту расходов строительной бригады.
Извлеки из фото чека данные и верни ТОЛЬКО JSON без markdown-обёртки:
{
  "date": "YYYY-MM-DD",
  "amount": число (итого к оплате, в рублях, с копейками через точку),
  "items": "краткое перечисление покупок через запятую",
  "shop_name": "название магазина или null",
  "category_guess": "одно из: materials, fuel, tools, food, delivery, other",
  "category_reason": "почему выбрал эту категорию, 5-10 слов"
}
Если дату не можешь прочитать — ставь null.
Если сумму не можешь прочитать — ставь 0.
Не выдумывай данных, только то что видишь на чеке.`
        }
      ]
    }
  ],
  temperature: 0,
  max_tokens: 2000
});

return [{ json: {
  request_body,
  user_name: trigger.message.from.first_name || 'Unknown',
  user_id: trigger.message.from.id,
  chat_id: trigger.message.chat.id
}}];

const response = $input.first().json;
let raw = response.choices[0].message.content;

// Убираем markdown-обёртку
raw = raw.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

// Убираем возможные управляющие символы
raw = raw.replace(/[\x00-\x1F\x7F]/g, (ch) => {
  if (ch === '\n' || ch === '\r' || ch === '\t') return ch;
  return '';
});

let content;
try {
  content = JSON.parse(raw);
} catch (e) {
  // Попытка починить обрезанный JSON
  // Закрываем незакрытые строки и объект
  let fixed = raw;
  if (!fixed.endsWith('}')) {
    // Обрезаем до последней полной пары key:value
    const lastComma = fixed.lastIndexOf(',');
    const lastColon = fixed.lastIndexOf(':');
    if (lastComma > lastColon) {
      fixed = fixed.substring(0, lastComma);
    }
    // Закрываем незакрытую строку
    const quoteCount = (fixed.match(/"/g) || []).length;
    if (quoteCount % 2 !== 0) {
      fixed += '"';
    }
    fixed += '}';
  }
  try {
    content = JSON.parse(fixed);
  } catch (e2) {
    // Если совсем не парсится — возвращаем дефолт
    content = {
      date: null,
      amount: 0,
      items: raw.substring(0, 200),
      shop_name: null,
      category_guess: 'other',
      category_reason: 'не удалось распознать'
    };
  }
}

const prev = $('Build Vision Request').first().json;

const now = new Date();
const pad = (n) => String(n).padStart(2, '0');
const dateStr = `${now.getFullYear()}${pad(now.getMonth()+1)}${pad(now.getDate())}`;
const seq = String(Math.floor(Math.random() * 999) + 1).padStart(3, '0');
const expense_id = `SU-${dateStr}-${seq}`;

const validCats = ['materials', 'fuel', 'tools', 'food', 'delivery', 'other'];
const category = validCats.includes(content.category_guess) ? content.category_guess : 'other';

return [{
  json: {
    expense_id,
    date: content.date || now.toISOString().slice(0, 10),
    amount: content.amount || 0,
    category,
    category_reason: content.category_reason || '',
    description: content.items || '',
    shop_name: content.shop_name || '',
    submitted_by: prev.user_name,
    telegram_user_id: String(prev.user_id),
    chat_id: prev.chat_id,
    created_at: now.toISOString()
  }
}];

const receipt = $('Parse Receipt').first().json;
const objects = $('Get Objects').all()
