const text = `📋 *Новый чек*\n\n` +
  `📅 Дата: ${receipt.date}\n` +
  `💰 Сумма: ${receipt.amount} ₽\n` +
  `🏷 Категория: ${catLabels[receipt.category] || receipt.category}\n` +
  `🏗 Объект: ${matched_name}\n` +
  `📝 ${receipt.description}\n` +
  `🏪 ${receipt.shop_name || 'Не указан'}\n\n` +
  `Всё верно?`;

const eid = receipt.expense_id;

const keyboard = {
