const expense = $('Get Expense Row').first().json;
const cb = $('Parse Callback').first().json;

// Если объект не назначен — пропускаем
if (!expense.object_id || expense.object_id === '') {
  return [{ json: { over_budget: false } }];
}

// Сумма confirmed расходов по объекту
const allExpenses = $('Get Expenses for Budget').all().map(i => i.json);
const objectExpenses = allExpenses.filter(
  e => e.object_id === expense.object_id && e.status === 'confirmed'
);
const totalSpent = objectExpenses.reduce((sum, e) => sum + Number(e.amount || 0), 0);

// Бюджет объекта
const objects = $('Get Object Budget').all().map(i => i.json);
const obj = objects.find(o => o.object_id === expense.object_id);
const budget = obj ? Number(obj.budget || 0) : 0;

// Процент
const pct = budget > 0 ? Math.round(totalSpent / budget * 100) : 0;
const overBudget = pct >= 80;

const alertText = overBudget
  ? `⚠️ *Внимание!*\n\nПо объекту «${obj.object_name}» израсходовано *${pct}%* бюджета.\n\n💰 Потрачено: ${totalSpent} ₽ из ${budget} ₽`
  : '';

return [{
  json: {
    over_budget: overBudget,
    pct,
    total_spent: totalSpent,
    budget,
    alert_text: alertText,
    chat_id: cb.chat_id
  }
}];

